-- Pack fr — what a project must comply with: planning authorisations,
-- environmental assessment, solar obligations, tertiary energy, energy labels.
set search_path = nexgen, public, extensions;

insert into rules (code, name, section, country, regions, applies_to, statement, parameters, legal_source_code, article, url, valid_from, valid_to, published_by, notes) values
  -- Planning: ground-mounted and carport photovoltaics.
  ('fr_pv_ground_exempt', 'Ground photovoltaics under 3 kWc and 1.80 m: no authorisation', 'compliance', 'FR', '{}', 'device',
   'A ground-mounted installation below 3 kWc whose height does not exceed 1.80 m needs no planning authorisation, except in a protected perimeter (surroundings of a historic monument, remarkable heritage site, classified site) where a prior declaration is due.',
   '{"max_power_kwp": 3, "max_height_m": 1.8, "exclusive_power": true, "except": "protected perimeters"}',
   'fr_code_urbanisme', 'R. 421-2', 'https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000050555215', null, null, 'pack:fr', null),
  ('fr_pv_ground_prior_declaration_1mw', 'Ground photovoltaics up to 1 MWc: prior declaration', 'compliance', 'FR', '{}', 'device',
   'A ground-mounted installation of 3 kWc or more and below 1 MWc, or below 3 kWc and higher than 1.80 m, is filed as a prior declaration of works.',
   '{"min_power_kwp": 3, "max_power_kwp": 1000, "exclusive_max": true}',
   'fr_code_urbanisme', 'R. 421-9', 'https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000050555227', '2022-12-30', '2024-11-30', 'pack:fr', 'Threshold set by the décret n° 2022-1688 du 26 décembre 2022; raised to 3 MWc on 1 December 2024.'),
  ('fr_pv_ground_prior_declaration', 'Ground photovoltaics up to 3 MWc: prior declaration', 'compliance', 'FR', '{}', 'device',
   'For applications filed from 1 December 2024, a ground-mounted or carport installation of 3 kWc or more and below 3 MWc, or below 3 kWc and higher than 1.80 m, is filed as a prior declaration of works; in a protected perimeter the building permit applies instead.',
   '{"min_power_kwp": 3, "max_power_kwp": 3000, "exclusive_max": true, "protected_perimeter": "building permit"}',
   'fr_code_urbanisme', 'R. 421-9, as amended by the décret n° 2024-1023', 'https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000050555227', '2024-12-01', null, 'pack:fr', null),
  ('fr_pv_ground_building_permit_1mw', 'Ground photovoltaics of 1 MWc and more: building permit', 'compliance', 'FR', '{}', 'device',
   'A ground-mounted installation of 1 MWc or more needs a building permit.',
   '{"min_power_kwp": 1000}',
   'fr_code_urbanisme', 'R. 421-1', 'https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000050555221', '2022-12-30', '2024-11-30', 'pack:fr', 'Raised to 3 MWc on 1 December 2024.'),
  ('fr_pv_ground_building_permit', 'Ground photovoltaics of 3 MWc and more: building permit', 'compliance', 'FR', '{}', 'device',
   'For applications filed from 1 December 2024, a ground-mounted or carport installation of 3 MWc or more needs a building permit.',
   '{"min_power_kwp": 3000}',
   'fr_code_urbanisme', 'R. 421-1, as amended by the décret n° 2024-1023', 'https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000050555221', '2024-12-01', null, 'pack:fr', null),
  -- Planning: photovoltaics on an existing building.
  ('fr_pv_roof_prior_declaration', 'Photovoltaics on an existing roof: prior declaration', 'compliance', 'FR', '{}', 'surface',
   'Panels on an existing building change its external aspect: the works are filed as a prior declaration with the municipality, whatever the power. In the surroundings of a historic monument or a remarkable heritage site, the architect of the Bâtiments de France gives an opinion the municipality follows.',
   '{"any_power": true, "heritage_opinion": "architecte des Bâtiments de France"}',
   'fr_code_urbanisme', 'R. 421-17', 'https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000045483355', null, null, 'pack:fr', null),
  -- Environmental assessment.
  ('fr_pv_environmental_assessment', 'Ground photovoltaics of 1 MWc and more: environmental assessment', 'compliance', 'FR', '{}', 'device',
   'A ground-mounted photovoltaic installation of 1 MWc or more goes through a full environmental assessment (impact study, public inquiry); carports on car parks are treated apart.',
   '{"min_power_kwp": 1000, "procedure": "systematic"}',
   'fr_code_environnement', 'R. 122-2, annexed table, item 30', 'https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000046005015', '2022-07-03', null, 'pack:fr', 'A 2026 decree raising this threshold to 3 MWc is reported by secondary sources: check the consolidated item 30 before relying on 1 MWc.'),
  ('fr_pv_environmental_case_by_case', 'Ground photovoltaics from 300 kWc to 1 MWc: case-by-case examination', 'compliance', 'FR', '{}', 'device',
   'A ground-mounted photovoltaic installation of 300 kWc or more and below 1 MWc is submitted to the environmental authority, which decides case by case whether an assessment is due.',
   '{"min_power_kwp": 300, "max_power_kwp": 1000, "exclusive_max": true, "procedure": "case by case"}',
   'fr_decret_2022_970_ee', 'Article 2 (item 30 of the table of R. 122-2)', 'https://www.legifrance.gouv.fr/jorf/id/JORFTEXT000046000733', '2022-07-03', null, 'pack:fr', null),
  -- Solar obligations.
  ('fr_solar_obligation_new_buildings', 'New commercial buildings of 500 m² and more carry solar or vegetation on part of the roof', 'compliance', 'FR', '{}', 'building',
   'A new building, or an extension or heavy renovation, of commercial, industrial, craft, warehouse or hangar use of 500 m² of floor area and more, or of office use of 1 000 m² and more, carries on its roof either a renewable energy production system or a vegetated system, on 30 % of the roof since 1 July 2023, 40 % from 1 July 2026 and 50 % from 1 July 2027; the same holds for covered car parks.',
   '{"min_floor_area_m2": 500, "min_floor_area_offices_m2": 1000, "share_by_date": {"2023-07-01": 0.3, "2026-07-01": 0.4, "2027-07-01": 0.5}}',
   'fr_cch', 'L. 171-4', 'https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000047302563', '2023-07-01', null, 'pack:fr', 'Shares from 2026 and 2027 come from the loi APER (article 41); the loi du 30 avril 2025 removed the option of carrying the obligation over to a car park. Read the consolidated article before relying on the shares.'),
  ('fr_solar_obligation_parkings_existing', 'Outdoor car parks of 1 500 m² and more: shade structures with solar on half the surface', 'compliance', 'FR', '{}', 'parking',
   'An existing outdoor car park of more than 1 500 m² is covered, on at least half its surface, by shade structures carrying a renewable energy production system, by 1 July 2026 for parks of more than 10 000 m² and by 1 July 2028 for parks of 1 500 m² to 10 000 m²; a park under concession follows the renewal of its contract between those dates. The owner answers for it.',
   '{"min_area_m2": 1500, "exclusive_min": true, "covered_share": 0.5, "deadline_by_area": {"10000": "2026-07-01", "1500": "2028-07-01"}, "responsible": "owner"}',
   'fr_loi_aper_2023', 'Article 40', 'https://www.legifrance.gouv.fr/jorf/article_jo/JORFARTI000047294302', '2023-07-01', null, 'pack:fr', 'The loi du 26 novembre 2025 opened a postponement for parks of 1 500 m² to 10 000 m² that show a supply contract for high-performance panels.'),
  ('fr_solar_obligation_parkings_new', 'New or renovated car parks of 500 m² and more: solar or vegetation', 'compliance', 'FR', '{}', 'parking',
   'A new outdoor car park, or one under heavy renovation, of more than 500 m² carries, on half its surface, shade structures with a renewable energy production system or vegetated devices, and keeps its soil permeable or planted.',
   '{"min_area_m2": 500, "exclusive_min": true, "covered_share": 0.5}',
   'fr_code_urbanisme', 'L. 111-19-1', 'https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000047302587', '2023-07-01', null, 'pack:fr', 'Harmonised with article 40 of the loi APER by the décret n° 2024-1023 du 13 novembre 2024.'),
  -- Tertiary buildings.
  ('fr_tertiary_energy_reduction', 'Tertiary buildings of 1 000 m² and more cut their final energy: 40 % in 2030, 50 % in 2040, 60 % in 2050', 'compliance', 'FR', '{}', 'building',
   'A building, part of a building or group of buildings on one site of tertiary use of 1 000 m² of floor area and more reduces its final energy consumption by 40 % in 2030, 50 % in 2040 and 60 % in 2050 against a reference year no earlier than 2010, or reaches an absolute value set by order; owners and occupiers declare the consumption of each year on the OPERAT platform by 30 September of the next year.',
   '{"min_floor_area_m2": 1000, "reduction_by_year": {"2030": 0.4, "2040": 0.5, "2050": 0.6}, "reference_year_min": 2010, "declaration": "OPERAT", "declaration_deadline": "09-30"}',
   'fr_decret_2019_771_tertiaire', 'Articles R. 174-22 and following of the CCH', 'https://www.legifrance.gouv.fr/jorf/id/JORFTEXT000038812251', '2019-10-01', null, 'pack:fr', null),
  -- Energy performance certificate.
  ('fr_dpe_classes', 'The energy classes of a dwelling, A to G, on primary energy and greenhouse gas', 'compliance', 'FR', '{}', 'building',
   'The energy performance certificate of a dwelling gives one class from A to G, the worse of its primary energy use and of its greenhouse gas emissions per square metre and year: A up to 70 kWh and 6 kg CO2, B up to 110 and 11, C up to 180 and 30, D up to 250 and 50, E up to 330 and 70, F up to 420 and 100, G beyond.',
   '{"primary_energy_kwh_m2_year_max": {"A": 70, "B": 110, "C": 180, "D": 250, "E": 330, "F": 420}, "ghg_kgco2_m2_year_max": {"A": 6, "B": 11, "C": 30, "D": 50, "E": 70, "F": 100}, "class": "worse of the two"}',
   'fr_arrete_2021_03_31_dpe', 'Annexe 1', 'https://www.legifrance.gouv.fr/loda/id/JORFTEXT000043353381/', '2021-07-01', null, 'pack:fr', 'Dwellings of 40 m² and less follow adapted thresholds since 1 July 2024 (arrêté du 25 mars 2024); the primary energy factor of electricity moved from 2.3 to 1.9 on 1 January 2026.'),
  ('fr_dpe_rental_ban', 'Dwellings of class G, then F, then E may no longer be let', 'compliance', 'FR', '{}', 'building',
   'A dwelling is decent, and may be let, only above an energy threshold: class G is excluded from 1 January 2025, class F from 1 January 2028, class E from 1 January 2034.',
   '{"excluded_from": {"G": "2025-01-01", "F": "2028-01-01", "E": "2034-01-01"}}',
   'fr_loi_climat_2021', 'Article 160', 'https://www.legifrance.gouv.fr/jorf/article_jo/JORFARTI000043957218', '2025-01-01', null, 'pack:fr', null);
